import{_ as t,o as i,c as a,a2 as n}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse(`{"title":"Product Definition and Boundaries","description":"Hearth's one-sentence positioning, what it is and is not, primary users, explicit non-goals, and experience commitments.","frontmatter":{"title":"Product Definition and Boundaries","description":"Hearth's one-sentence positioning, what it is and is not, primary users, explicit non-goals, and experience commitments.","outline":[2,3]},"headers":[],"relativePath":"en/product/definition.md","filePath":"en/product/definition.md","lastUpdated":1793706118000}`),o={name:"en/product/definition.md"};function r(s,e,l,d,c,h){return i(),a("div",null,[...e[0]||(e[0]=[n('<p class="eyebrow">PRODUCT DEFINITION</p><h1 id="product-definition-and-boundaries" tabindex="-1">Product Definition and Boundaries <a class="header-anchor" href="#product-definition-and-boundaries" aria-label="Permalink to &quot;Product Definition and Boundaries&quot;">​</a></h1><p class="lead">Who Hearth is for, what problem it solves, and what it explicitly does not promise. Establish the boundaries first, then discuss architecture and implementation.</p><h2 id="one-sentence-positioning" tabindex="-1">One-Sentence Positioning <a class="header-anchor" href="#one-sentence-positioning" aria-label="Permalink to &quot;One-Sentence Positioning&quot;">​</a></h2><blockquote><p><strong>Hearth is a general-purpose personal Agent OS with personal context, durable execution, real tools, and multi-device entry points; it frees people from repetitive digital labor instead of creating another chat window that needs supervision.</strong></p></blockquote><p>It is a single-user, self-hosted, long-lived, low-distraction, low-Token personal Agent OS. The product name is Hearth, the suggested repository is <code>hearth-os</code>, the command line is <code>hearth</code>, the resident service is <code>hearthd</code>, and the package namespace is <code>@hearth/*</code>.</p><h2 id="what-it-is-and-what-it-is-not" tabindex="-1">What It Is and What It Is Not <a class="header-anchor" href="#what-it-is-and-what-it-is-not" aria-label="Permalink to &quot;What It Is and What It Is Not&quot;">​</a></h2><p>Hearth is not:</p><ul><li>another Coding Agent;</li><li>a Codex wrapper that only forwards prompts;</li><li>a black-box automation that hands all permissions to the model;</li><li>an assistant that only answers questions in a chat box;</li><li>an enterprise multi-tenant Agent platform;</li><li>a tool that requires users to maintain prompts, plugins, and workflows every day.</li></ul><p>Hearth is:</p><ul><li><strong>Control Plane</strong>: decides what to do, whether it is permitted, when to interrupt, and how to recover;</li><li><strong>Durable Harness</strong>: turns intent into recoverable, auditable execution with Receipts;</li><li><strong>A peer set of Executors</strong>: Native, Codex, Connector, Browser, GUI, Document/Data, Human;</li><li><strong>Memory OS</strong>: makes people, projects, preferences, commitments, and experience safely recallable;</li><li><strong>Evolution OS</strong>: distills repeated success into skills, but changes must go through evaluation and rollback;</li><li><strong>Experience Plane</strong>: carries interaction through Task cards, approvals, and Artifacts rather than an endless chat history.</li></ul><h2 id="target-user" tabindex="-1">Target User <a class="header-anchor" href="#target-user" aria-label="Permalink to &quot;Target User&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Assumption</th></tr></thead><tbody><tr><td>User</td><td>1 primary user, possibly 1–3 trusted collaborators</td></tr><tr><td>Devices</td><td>One primary computer, one always-on machine, one phone</td></tr><tr><td>Work</td><td>A mix of research, writing, documentation, email, calendar, code, Issues, PRs, data, and web operations</td></tr><tr><td>Technical skill</td><td>Able to run local services, but does not want to maintain Agent configuration daily</td></tr><tr><td>Privacy requirements</td><td>Personal files and credentials must not be uploaded by default to untrusted third parties</td></tr><tr><td>Usage mode</td><td>Proactive Tasks, scheduled Tasks, notification-triggered Tasks, and manual initiation coexist</td></tr></tbody></table><p>The first version does not aim for “everyone can use it”; it aims for “one real user is willing to use it every day.”</p><h2 id="what-it-explicitly-does-not-promise" tabindex="-1">What It Explicitly Does Not Promise <a class="header-anchor" href="#what-it-explicitly-does-not-promise" aria-label="Permalink to &quot;What It Explicitly Does Not Promise&quot;">​</a></h2><ul><li>physical-world robot operation;</li><li>assuming legal, medical, financial, or other professional responsibility on the user&#39;s behalf;</li><li>unapproved payments, contract signing, deletions, public releases, or permission changes;</li><li>100% unattended operation of arbitrary software;</li><li>enterprise IAM, multi-tenancy, organizational audit, and billing;</li><li>covering all eight Task categories on day one;</li><li>competing with underlying model vendors on model capability;</li><li>creating the illusion of “being human” through unbounded autonomous loops.</li></ul><h2 id="experience-commitments" tabindex="-1">Experience Commitments <a class="header-anchor" href="#experience-commitments" aria-label="Permalink to &quot;Experience Commitments&quot;">​</a></h2><ul><li>The user can see at a glance what the Agent is doing;</li><li>When a human is needed, only one clear action appears;</li><li>The user does not need to understand internal jargon such as Worker, Harness, or Token;</li><li>The phone can handle viewing, approvals, takeover, and initiation;</li><li>For any failure, the cause and recovery options are visible;</li><li>Notifications are predictable;</li><li>Starting from the first runnable increment, users can complete Tasks through a real interface, rather than only seeing capabilities in the CLI, logs, or tests.</li></ul>',18)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
